    "source_exam": "ABPMR PM&R100 Part I (June 2015 release)",
    "question_text": "When using a spinal cord stimulator for the management of neuropathic pain, electrodes are placed into which space?",
    "option_a": "Epidural",
    "option_b": "Subarachnoid",
    "option_c": "Interdiskal",
