    "id": "pmr100-97",
    "source_exam": "ABPMR PM&R100 Part I (June 2015 release)",
    "question_text": "What is the most commonly used switch access method for alternative and augmentative communication devices?",
    "option_a": "Picture text scanning",
    "option_b": "Noun verb scanning",
    "option_c": "Row column scanning",
    "option_d": "Line checkbox scanning",
